const val=id=>$(id)?.value?.trim()||'';
const options=(data,key='name',placeholder='Select an option')=>`<option value="">${esc(placeholder)}</option>`+data.map(x=>`<option value="${esc(x.id)}">${esc(x[key]||x.full_name||x.title||x.id)}</option>`).join('');
const field=(label,id,kind='text',extra='')=>`<div class="field"><label for="${id}">${esc(label)}</label><input id="${id}" type="${kind}" ${extra}></div>`;
const selectField=(label,id,opts)=>`<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}">${opts}</select></div>`;
const area=(label,id,placeholder='')=>`<div class="field full"><label for="${id}">${esc(label)}</label><textarea id="${id}" placeholder="${esc(placeholder)}"></textarea></div>`;
const empty=(title='Nothing here yet',sub='Records will appear here once they are added.')=>`<div class="placeholder"><span class="emoji">✦</span><b>${esc(title)}</b><p class="muted">${esc(sub)}</p></div>`;
const tag=(text,kind='gray')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const btn=(label,id,kind='')=>`<button class="btn ${kind}" id="${id}" type="button">${label}</button>`;
