const icons={'Demo Showcase':'✧','Overview':'▦','Students':'♧','Staff':'♙','Classes & Subjects':'▤','My Classes':'▤','Lessons':'▣','Examinations':'✎','Take Exam':'✎','Marking':'✓','My Results':'★','Attendance':'◷','Assessments':'☷','Report Cards':'▥','Announcements':'◈','Parents':'♡','My Children':'♧'};
