let toastTimeout;
function toast(text,error=false){let el=$('toast');if(!el){el=document.createElement('div');el.id='toast';el.style.cssText='position:fixed;bottom:23px;right:23px;max-width:430px;padding:15px 20px;border-radius:12px;background:#32263a;color:white;box-shadow:0 15px 35px #30203533;z-index:9000;font-size:13px;line-height:1.5';document.body.append(el);}el.style.background=error?'#922640':'#32263a';el.textContent=text;el.hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.hidden=true,6200);}
async function data(q){const r=await q;if(r.error)throw new Error(r.error.message);return r.data??[];}
function isStaff(){return ['admin','teacher'].includes(profile?.role)}
function requireRole(...r){if(!r.includes(profile?.role)){toast('Your account does not have permission for this action.',true);return false;}return true;}
function stat(label,num,icon='▦',meta='') {return `<div class="stat"><span class="icon">${icon}</span><div class="muted tiny">${esc(label)}</div><b>${esc(num)}</b><span class="meta">${esc(meta)}</span></div>`;}
function listTable(rows,headers,renderRow){if(!rows?.length)return empty('No records found','New records will appear here when available.');return `<div class="scroll"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(renderRow).join('')}</tbody></table></div>`;}
function setPage(content){if(localTimer){clearInterval(localTimer);localTimer=null;}const name=esc(profile?.full_name||user.email||'');const items=navGroups[profile.role]||navGroups.student;root.innerHTML=`<div class="shell"><aside><div class="brand"><img class="academy-logo" src="https://torchbearersacademy.com/secure.accounts/ServiceLoginAuth/services/efactory/images/companylogo/logo/mainlogotorchbearers.png" alt="Torch Bearers Academy logo" onerror="this.hidden=true;this.nextElementSibling.style.display='grid'"><span class="brand-mark" style="display:none">T</span><div class="brand-name">Torch Bearers<small>ACADEMY · ALWAYS AHEAD</small></div></div><div class="side-label">WORKSPACE</div><div class="nav">${items.map(n=>`<button class="nav-btn ${n===tab?'active':''}" data-tab="${esc(n)}"><span class="nav-icon">${icons[n]||'◈'}</span>${esc(n)}</button>`).join('')}</div><div class="side-bottom"><b>✦ Always Ahead</b><span class="tiny">A smarter school experience for every learner.</span></div></aside><main><header class="topbar"><div><div class="eyebrow">Torch Bearers Academy</div><h1>${esc(tab)}</h1><p class="page-sub">${esc(roleName[profile.role]||'School Portal')} workspace</p></div><div class="top-actions"><span class="hide-mobile tiny muted">${name}</span><div class="avatar">${esc(name[0]||'T').toUpperCase()}</div><button id="logout" class="btn secondary small">Sign out</button></div></header><section id="page">${content}</section><p class="footer-note">© ${new Date().getFullYear()} Torch Bearers Academy · Always Ahead · Academic information is accessible only by authorized accounts. · Benin City · enquiries@torchbearersacademy.com · 09060090756</p></main></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));$('logout').onclick=()=>db.auth.signOut();}
function loading(){setPage('<div class="card">Loading your school records…</div>');}
async function go(next){tab=next;activeVersion++;const v=activeVersion;loading();try{await pages[next]?.();if(v!==activeVersion)return;}catch(e){if(v===activeVersion){setPage(`<div class="notice error"><b>Could not load ${esc(tab)}</b><p>${esc(e.message)}</p></div>`);}}}
async function initialAdminSignup(){
 root.innerHTML=`<div class="login-screen"><div class="login-art"><div><div class="brand" style="border:0"><img class="academy-logo" src="https://torchbearersacademy.com/secure.accounts/ServiceLoginAuth/services/efactory/images/companylogo/logo/mainlogotorchbearers.png" alt="Torch Bearers Academy logo"><div class="brand-name">Torch Bearers<small>ACADEMY · ALWAYS AHEAD</small></div></div><div class="eyebrow" style="color:#f3c7de;margin:35px 0 10px">BENIN CITY</div><h1>Always Ahead</h1><p>Your school management experience begins here.</p></div></div><div class="login-form"><div class="login-panel"><div class="eyebrow">INITIAL SCHOOL SETUP</div><h2>Register the first administrator</h2><p class="muted">The first registered account becomes the school administrator. Other accounts are managed through administrator invitations.</p><form id="adminSignup"><div class="field"><label>Full name</label><input id="adminFullName" maxlength="160" minlength="2" required autocomplete="name"></div><div class="field"><label>Email address</label><input id="adminEmail" type="email" required autocomplete="email"></div><div class="field"><label>Password (at least 10 characters)</label><input id="adminPassword" type="password" minlength="10" required autocomplete="new-password"></div><div class="field"><label>Confirm password</label><input id="adminConfirm" type="password" minlength="10" required autocomplete="new-password"></div><button class="btn" type="submit">Create administrator account →</button><p id="adminSignupNotice" class="tiny muted"></p></form><button class="btn secondary" style="width:100%;margin-top:12px" id="goLogin">Already have an account? Sign in</button><p class="tiny muted">Torch Bearers Academy · Benin City · Always Ahead</p></div></div></div>`;
 $('goLogin').onclick=login;
 $('adminSignup').onsubmit=async e=>{e.preventDefault();const notice=$('adminSignupNotice');if(val('adminPassword')!==val('adminConfirm')){notice.textContent='Passwords must match.';return;}const button=e.target.querySelector('button[type=submit]');button.disabled=true;const response=await db.auth.signUp({email:val('adminEmail'),password:val('adminPassword'),options:{data:{full_name:val('adminFullName')},emailRedirectTo:location.origin}});button.disabled=false;if(response.error){notice.textContent=response.error.message;return;}if(response.data?.session){await bootstrap();return;}notice.textContent='Account created. Please verify your email if requested, then sign in.';};
}
async function entryScreen(){const status=await db.rpc('academy_bootstrap_available');if(!status.error && status.data===true)initialAdminSignup();else login();}
function login(){root.innerHTML=`<div class="login-screen"><div class="login-art"><div><div class="brand" style="border:0"><img class="academy-logo" src="https://torchbearersacademy.com/secure.accounts/ServiceLoginAuth/services/efactory/images/companylogo/logo/mainlogotorchbearers.png" alt="Torch Bearers Academy logo" onerror="this.hidden=true;this.nextElementSibling.style.display='grid'"><span class="brand-mark" style="display:none">T</span><div class="brand-name">Torch Bearers<small>ACADEMY · ALWAYS AHEAD</small></div></div><div class="eyebrow" style="color:#f3c7de;margin:35px 0 10px">WELCOME TO YOUR SCHOOL PORTAL</div><h1>Learning, teaching and growing — together.</h1><p>One beautiful place for learning, academic records, assessments and communication across our school community.</p><div style="font-size:70px;margin-top:30px">✦</div></div></div><div class="login-form"><div class="login-panel"><div class="eyebrow">SECURE ACCESS</div><h2>Welcome back</h2><p class="muted">Sign in to your Torch Bearers Academy account.</p><form id="signin"><div class="field"><label>Email address</label><input id="email" type="email" placeholder="yourname@example.com" autocomplete="username" required></div><div class="field"><label>Password</label><input id="password" type="password" placeholder="Enter your password" autocomplete="current-password" required></div><button class="btn" type="submit">Sign in to portal →</button><p class="tiny muted">Only accounts registered by the academy are permitted to access this portal.</p><div id="signinNotice"></div></form><button class="btn secondary" style="width:100%;margin-top:10px" id="forgot">Reset password</button><div style="margin-top:55px" class="tiny muted">Torch Bearers Academy · Always Ahead</div></div></div></div>`;
 $('signin').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;let r=await db.auth.signInWithPassword({email:val('email'),password:val('password')});button.disabled=false;if(r.error)$('signinNotice').innerHTML=`<p class="notice error">${esc(r.error.message)}</p>`;};
 $('forgot').onclick=async()=>{const email=val('email');if(!email)return toast('Please enter your email address first.',true);const r=await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin});toast(r.error?.message||'If this address is registered, password reset instructions have been sent.',Boolean(r.error));};}
async function bootstrap(){const {data:s,error:e}=await db.auth.getSession();if(e||!s?.session?.user){user=null;profile=null;await entryScreen();return;}user=s.session.user;const r=await db.from('profiles').select('*').eq('id',user.id).maybeSingle();if(r.error){root.innerHTML=`<section class="card" style="max-width:600px;margin:80px auto"><h2>Unable to verify access</h2><p class="notice error">${esc(r.error.message)}</p><button class="btn" id="logout">Sign out</button></section>`;$('logout').onclick=()=>db.auth.signOut();return;}profile=r.data;if(!profile){root.innerHTML=`<section class="card" style="max-width:600px;margin:80px auto"><div class="eyebrow">Torch Bearers Academy</div><h2>Account awaiting approval</h2><p>Your account has not been assigned a school profile. Ask an administrator to enroll you. No student information is available until your account has an authorized role.</p><p class="muted">Account: ${esc(user.email)}</p><button class="btn" id="logout">Sign out</button></section>`;$('logout').onclick=()=>db.auth.signOut();return;}if(!(navGroups[profile.role]||[]).includes(tab))tab='Overview';await go(tab);}
const [schoolName,schoolMotto]=['Torch Bearers Academy','Always Ahead'];

async function overview(){const [classes,subjects,students,notes,announcements,exams]=await Promise.all([
 data(db.from('classes').select('id,name').limit(500)),data(db.from('subjects').select('id,name').limit(500)),
 data(db.from('profiles').select('id,role,full_name').limit(500)),data(db.from('lesson_notes').select('id').limit(500)),
 data(db.from('announcements').select('id,title,created_at,body').order('created_at',{ascending:false}).limit(4)),data(db.from('exams').select('id,published').limit(500))]);
 const studentCount=students.filter(x=>x.role==='student').length;
 const cards=profile.role==='admin'?[['Students',studentCount,'♧','Enrolled profiles'],['Classes',classes.length,'▤','Academic classes'],['Subjects',subjects.length,'◈','Learning subjects'],['Examinations',exams.length,'✎','Created assessments']]:profile.role==='teacher'?[['Classes',classes.length,'▤','Visible classes'],['Lesson Notes',notes.length,'▣','Your learning resources'],['Examinations',exams.length,'✎','Owned assessments'],['Students',studentCount,'♧','Directory access']]:[['Classes',classes.length,'▤','Academic levels'],['Published Exams',exams.filter(e=>e.published).length,'✎','Exams available by class'],['Lesson Notes',notes.length,'▣','Your resources'],['Announcements',announcements.length,'◈','Recent updates']];
 const actions=(profile.role==='admin'?['Students','Classes & Subjects','Examinations','Announcements']:profile.role==='teacher'?['Lessons','Examinations','Attendance','Assessments']:profile.role==='student'?['Take Exam','Lessons','My Results','Attendance']:['My Children','Report Cards','Attendance','Announcements']);
 setPage(`<div class="hero"><div><div class="eyebrow">${esc(new Date().toLocaleDateString('en-NG',{weekday:'long',month:'long',day:'numeric'}))}</div><h2>Welcome, ${esc((profile.full_name||'there').split(' ')[0])} 👋</h2><p>Everything you need for another productive day at ${schoolName}. Let's keep moving ahead.</p></div><span class="hide-mobile" style="font-size:75px;z-index:1">✦</span></div><div class="cards">${cards.map(x=>stat(...x)).join('')}</div><div class="split"><div class="card"><div class="row between"><h2>Recent announcements</h2><button class="btn secondary small" id="allNews">View all →</button></div>${announcements.length?announcements.map(n=>`<div style="padding:14px 0;border-bottom:1px solid #eee5eb"><b>${esc(n.title)}</b><div class="tiny muted">${fmtDate(n.created_at)}</div><p class="tiny">${esc(n.body).slice(0,260)}</p></div>`).join(''):empty('No announcements','School announcements will appear here.')}</div><div class="card"><h2>Quick access</h2><p class="muted tiny">Jump into the tools you use most.</p><div class="stack">${actions.map(a=>`<button class="link-tile" data-jump="${a}"><b>${icons[a]} ${esc(a)} →</b><small>Open ${esc(a.toLowerCase())}</small></button>`).join('')}</div></div></div>`);
 $('allNews').onclick=()=>go('Announcements');document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));}

async function adminSetup(){if(!requireRole('admin'))return;const [classes,subjects,sessions,students,teachers,parents,assignments,enrollments]=await Promise.all([
 data(db.from('classes').select('*').order('name')),data(db.from('subjects').select('*').order('name')),
 data(db.from('academic_sessions').select('*').order('name',{ascending:false})),data(db.from('profiles').select('id,full_name,role').eq('role','student').order('full_name')),
 data(db.from('profiles').select('id,full_name,role').eq('role','teacher').order('full_name')),data(db.from('profiles').select('id,full_name,role').eq('role','parent').order('full_name')),
 data(db.from('teacher_assignments').select('id,class_id,subject_id,teacher_id').limit(500)),data(db.from('enrollments').select('id,class_id,student_id').limit(500))]);
 const classMap=Object.fromEntries(classes.map(c=>[c.id,c.name])), subjectMap=Object.fromEntries(subjects.map(s=>[s.id,s.name])),nameMap=Object.fromEntries([...students,...teachers,...parents].map(p=>[p.id,p.full_name]));
 setPage(`<div class="card"><h2>Academic setup</h2><p class="muted">Create sessions, classes and subjects, then assign teachers and enroll students.</p><div class="form-grid"><div>${field('Session name','newSession','text','placeholder="e.g. 2026/2027"')}${btn('Add session','addSession')}</div><div>${field('Class name','newClass','text','placeholder="e.g. JSS 2A"')}${selectField('Academic session','newClassSession',options(sessions))}${btn('Add class','addClass')}</div><div>${field('Subject name','newSubject','text','placeholder="e.g. Mathematics"')}${btn('Add subject','addSubject')}</div></div></div><div class="split"><div class="card"><h3>Classes (${classes.length})</h3>${listTable(classes,['Class','Session'],r=>`<tr><td>${esc(r.name)}</td><td>${esc(sessions.find(s=>s.id===r.session_id)?.name||'Not assigned')}</td></tr>`)}</div><div class="card"><h3>Subjects (${subjects.length})</h3>${listTable(subjects,['Subject'],r=>`<tr><td>${esc(r.name)}</td></tr>`)}</div></div><div class="card"><h2>Teacher assignment</h2><div class="form-grid">${selectField('Teacher','teacherId',options(teachers,'full_name'))}${selectField('Subject','teacherSubject',options(subjects))}<div class="field"><label>Classes (select any number)</label><div class="scroll" style="max-height:180px;border:1px solid #e8d8e0;border-radius:12px;padding:12px">${classes.map(c=>`<label style="display:block;margin:7px 0"><input type="checkbox" class="assignClass" value="${esc(c.id)}" style="width:auto;margin-right:8px">${esc(c.name)}</label>`).join('')}</div><p class="tiny muted">For example, assign Mathematics to JSS 1, JSS 2, SS 1 and SS 2 in a single action.</p></div></div>${btn('Assign teacher to selected classes','assignTeacher')}<h3 style="margin-top:22px">Existing assignments</h3>${listTable(assignments,['Teacher','Class','Subject','Action'],r=>`<tr><td>${esc(nameMap[r.teacher_id]||r.teacher_id)}</td><td>${esc(classMap[r.class_id])}</td><td>${esc(subjectMap[r.subject_id])}</td><td><button class="btn secondary small" data-unassign="${esc(r.id)}">Remove</button></td></tr>`)}</div><div class="card"><h2>Student enrollment</h2><div class="form-grid">${selectField('Student','enrollStudent',options(students,'full_name'))}${selectField('Class','enrollClass',options(classes))}</div>${btn('Enroll student','enrollButton')}<p class="muted tiny">Students must have school-issued authentication accounts before enrollment.</p><h3 style="margin-top:22px">Class enrollments (${enrollments.length})</h3>${listTable(enrollments,['Student','Class'],r=>`<tr><td>${esc(nameMap[r.student_id]||r.student_id)}</td><td>${esc(classMap[r.class_id]||r.class_id)}</td></tr>`)}</div>`);
 const action=async(table,row,opts)=>{const r=await db.from(table).insert(row);if(r.error)toast(r.error.message,true);else{toast('Saved successfully');await go('Classes & Subjects');}};
 $('addSession').onclick=()=>val('newSession')&&action('academic_sessions',{name:val('newSession'),school_id:profile.school_id,active:sessions.length===0});
 $('addClass').onclick=()=>val('newClass')&&action('classes',{name:val('newClass'),session_id:val('newClassSession')||null,school_id:profile.school_id});
 $('addSubject').onclick=()=>val('newSubject')&&action('subjects',{name:val('newSubject'),school_id:profile.school_id});
 $('assignTeacher').onclick=async()=>{const ids=[...document.querySelectorAll('.assignClass:checked')].map(e=>e.value),teacher_id=val('teacherId'),subject_id=val('teacherSubject');if(!teacher_id||!subject_id||!ids.length)return toast('Choose a teacher, subject and at least one class.',true);const rows=ids.filter(id=>!assignments.some(a=>a.teacher_id===teacher_id&&a.subject_id===subject_id&&a.class_id===id)).map(class_id=>({teacher_id,class_id,subject_id}));if(!rows.length)return toast('The selected class and subject assignments already exist.',true);const r=await db.from('teacher_assignments').insert(rows);toast(r.error?.message||'Assigned teacher to '+rows.length+' class(es).',Boolean(r.error));if(!r.error)go('Classes & Subjects');};
 document.querySelectorAll('[data-unassign]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this teaching assignment?'))return;const r=await db.from('teacher_assignments').delete().eq('id',b.dataset.unassign);toast(r.error?.message||'Teaching assignment removed.',Boolean(r.error));if(!r.error)go('Classes & Subjects');});
 $('enrollButton').onclick=()=>val('enrollStudent')&&val('enrollClass')&&action('enrollments',{student_id:val('enrollStudent'),class_id:val('enrollClass')});}

async function studentDirectory(){if(!requireRole('admin'))return;const students=await data(db.from('profiles').select('id,full_name,admission_number,phone,created_at').eq('role','student').order('full_name'));
 setPage(`<div class="card"><div class="row between"><div><h2>Student directory</h2><p class="muted tiny">${students.length} student accounts in your school</p></div>${btn('Invite a student','inviteStudent','small')}</div>${listTable(students,['Student name','Admission no.','Phone','Actions'],r=>`<tr><td><b>${esc(r.full_name)}</b></td><td>${esc(r.admission_number||'—')}</td><td>${esc(r.phone||'—')}</td><td><button class="btn secondary small" data-student="${esc(r.id)}">Edit details</button></td></tr>`)}</div><div class="card" id="studentForm"><h3>Enroll a new school account</h3><p class="muted">Use the invite button to send a secure enrollment email. The school administrator must sign in before inviting users.</p></div>`);
 $('inviteStudent').onclick=()=>inviteForm('student');document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{const s=students.find(x=>x.id===b.dataset.student);$('studentForm').innerHTML=`<h3>Edit student details</h3>${field('Full name','editName','text',`value="${esc(s.full_name)}"`)}${field('Admission number','editAdm','text',`value="${esc(s.admission_number)}"`)}${field('Phone','editPhone','tel',`value="${esc(s.phone)}"`)}${btn('Save changes','updateStudent')}`;$('updateStudent').onclick=async()=>{let r=await db.from('profiles').update({full_name:val('editName'),admission_number:val('editAdm'),phone:val('editPhone')}).eq('id',s.id);toast(r.error?.message||'Student details saved',Boolean(r.error));if(!r.error)go('Students');};});}
async function staffDirectory(){if(!requireRole('admin'))return;const staff=await data(db.from('profiles').select('id,full_name,phone,role').in('role',['teacher','admin']).order('full_name'));setPage(`<div class="card"><div class="row between"><h2>School staff</h2>${btn('Invite staff','inviteStaff','small')}</div>${listTable(staff,['Full name','Role','Phone'],r=>`<tr><td>${esc(r.full_name)}</td><td>${tag(r.role)}</td><td>${esc(r.phone||'—')}</td></tr>`)}</div><div class="card" id="inviteBox"><p class="muted">Invite new teachers or administrators using their work email.</p></div>`);$('inviteStaff').onclick=()=>inviteForm('teacher');}
function inviteForm(defaultRole){if(!requireRole('admin'))return;const holder=$('studentForm')||$('inviteBox')||$('inviteHost');if(!holder)return;holder.innerHTML=`<h3>Send an account invitation</h3><div class="form-grid">${field('Full name','inviteName','text','required')}${field('Email address','inviteEmail','email','required')}${selectField('Account role','inviteRole',`<option value="${defaultRole}">${defaultRole}</option>`+['student','teacher','parent','admin'].filter(r=>r!==defaultRole).map(r=>`<option value="${r}">${r}</option>`).join(''))}${field('Admission number (student only)','inviteAdmission')}</div>${btn('Send secure invitation','sendInvitation')}<p class="tiny muted">An email invitation is sent through Supabase Auth. Existing accounts are not overwritten.</p>`;
 $('sendInvitation').onclick=async()=>{const full_name=val('inviteName'),email=val('inviteEmail'),role=val('inviteRole');if(!full_name||!email)return toast('Enter a full name and email',true);try{const {data:r,error}=await db.functions.invoke('school-invite',{body:{full_name,email,role,admission_number:val('inviteAdmission')}});if(error)throw error;if(r?.error)throw new Error(r.error);toast('Invitation sent. The user can activate their account through email.');}catch(e){toast(e.message||'Could not invite user. Verify that the invitation function is configured.',true)}};}
async function parentLinks(){if(!requireRole('admin'))return;const [parents,students,links]=await Promise.all([data(db.from('profiles').select('id,full_name').eq('role','parent')),data(db.from('profiles').select('id,full_name').eq('role','student')),data(db.from('parent_students').select('*'))]);const nm=Object.fromEntries([...parents,...students].map(x=>[x.id,x.full_name]));setPage(`<div class="card"><h2>Parent and guardian access</h2><p class="muted">Link each parent's school login to the relevant children. Parents can only see associated students.</p><div class="form-grid">${selectField('Parent','linkParent',options(parents,'full_name'))}${selectField('Student','linkStudent',options(students,'full_name'))}</div>${btn('Link parent to student','saveParent')}<div style="height:20px"></div>${listTable(links,['Parent','Student'],r=>`<tr><td>${esc(nm[r.parent_id])}</td><td>${esc(nm[r.student_id])}</td></tr>`)}</div><div class="card" id="inviteHost"><h3>Invite a parent</h3>${btn('Create parent invitation','inviteParent','secondary')}</div>`);$('saveParent').onclick=async()=>{if(!val('linkParent')||!val('linkStudent'))return;let r=await db.from('parent_students').insert({parent_id:val('linkParent'),student_id:val('linkStudent')});toast(r.error?.message||'Parent linked',Boolean(r.error));if(!r.error)go('Parents');};$('inviteParent').onclick=()=>inviteForm('parent');}

async function myClasses(){const [classes,subjects,links,enrollments]=await Promise.all([data(db.from('classes').select('*')),data(db.from('subjects').select('*')),data(db.from('teacher_assignments').select('*')),data(db.from('enrollments').select('*'))]);const cm=Object.fromEntries(classes.map(c=>[c.id,c.name])),sm=Object.fromEntries(subjects.map(s=>[s.id,s.name]));const my=profile.role==='teacher'?links.filter(l=>l.teacher_id===user.id):enrollments.filter(e=>e.student_id===user.id);
 setPage(`<div class="card"><h2>${profile.role==='teacher'?'Teaching assignments':'Your enrolled classes'}</h2>${listTable(my,profile.role==='teacher'?['Class','Subject','Students']:['Class','Session'],r=>profile.role==='teacher'?`<tr><td><b>${esc(cm[r.class_id]||'Unknown')}</b></td><td>${esc(sm[r.subject_id]||'Unknown')}</td><td>${enrollments.filter(e=>e.class_id===r.class_id).length}</td></tr>`:`<tr><td>${esc(cm[r.class_id]||'Unknown')}</td><td>${esc(classes.find(c=>c.id===r.class_id)?.session_id||'—')}</td></tr>`)}</div>`);}

async function lessons(){const [classes,subjects,notes]=await Promise.all([data(db.from('classes').select('id,name')),data(db.from('subjects').select('id,name')),data(db.from('lesson_notes').select('*').order('created_at',{ascending:false}).limit(100))]);const cm=Object.fromEntries(classes.map(c=>[c.id,c.name])),sm=Object.fromEntries(subjects.map(s=>[s.id,s.name]));const staff=isStaff();
 setPage(`${staff?`<div class="card"><div class="row between"><div><h2>AI-assisted lesson workspace</h2><p class="muted tiny">Create lesson notes from typing, speech or uploaded documents, then publish to your class.</p></div>${tag('Teacher workspace')}</div><div class="form-grid">${field('Lesson title','lessonTitle','text','placeholder="e.g. Introduction to Fractions"')}${selectField('Class','lessonClass',options(classes))}${selectField('Subject','lessonSubject',options(subjects))}<div class="field"><label>Upload a PDF, text file or image</label><input type="file" id="lessonFile" accept=".pdf,.txt,image/png,image/jpeg,image/webp"><span class="tiny muted">Text PDFs are extracted on-device. Image OCR requires configured AI service.</span></div>${area('Lesson notes','lessonBody','Write, dictate or import lesson materials here.')}</div><div class="row">${btn('🎙 Dictate','dictate','secondary')}${btn('✨ AI Summarize','summarize','secondary')}${btn('Save lesson','saveLesson')}${btn('Save & publish','publishLesson','dark')}</div><div class="notice" id="speechFeedback" hidden></div></div>`:''}<div class="card"><h2>${staff?'Saved lesson notes':'Class learning materials'}</h2>${listTable(notes,['Lesson','Class / subject','Date','Status','Actions'],r=>`<tr><td><b>${esc(r.title)}</b><div class="tiny muted">${esc((r.body||'').slice(0,90))}${(r.body||'').length>90?'…':''}</div></td><td>${esc(cm[r.class_id]||'General')} · ${esc(sm[r.subject_id]||'—')}</td><td>${fmtDate(r.created_at)}</td><td>${tag(r.published?'Published':'Draft',r.published?'green':'orange')}</td><td><button class="btn secondary small" data-note="${esc(r.id)}">Read</button></td></tr>`)}</div><div id="noteViewer"></div>`);
 document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{const n=notes.find(x=>x.id===b.dataset.note);$('noteViewer').innerHTML=`<div class="card"><div class="row between"><h2>${esc(n.title)}</h2>${staff&&n.teacher_id===user.id?btn(n.published?'Unpublish':'Publish','togglePublish','secondary'):''}</div><p style="white-space:pre-wrap">${esc(n.body)}</p></div>`;if($('togglePublish'))$('togglePublish').onclick=async()=>{let r=await db.from('lesson_notes').update({published:!n.published}).eq('id',n.id);toast(r.error?.message||'Visibility updated',Boolean(r.error));if(!r.error)go('Lessons');};});
 if(!staff)return;
 let recognition=null;
 $('dictate').onclick=()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return toast('Your browser does not support speech dictation. Try Chrome or Edge.',true);if(recognition){recognition.stop();recognition=null;$('dictate').textContent='🎙 Dictate';return;}recognition=new Speech();recognition.continuous=true;recognition.interimResults=false;recognition.lang='en-NG';recognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)$('lessonBody').value+=($('lessonBody').value?' ':'')+e.results[i][0].transcript};recognition.onerror=e=>toast('Dictation error: '+e.error,true);recognition.onend=()=>{$('dictate')&&($('dictate').textContent='🎙 Dictate');recognition=null};recognition.start();$('dictate').textContent='Stop dictation';};
 $('lessonFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>8*1024*1024)return toast('Please use a file under 8 MB.',true);try{let text='';if(f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf')){const pdf=await pdfjsLib.getDocument({data:new Uint8Array(await f.arrayBuffer())}).promise;for(let i=1;i<=Math.min(pdf.numPages,40);i++){const page=await pdf.getPage(i),content=await page.getTextContent();text+='\n'+content.items.map(x=>x.str||'').join(' ');}if(!text.trim())throw new Error('This PDF appears scanned. Upload a page image for OCR, or enter text manually.');}else if(f.type.startsWith('image/')){const base64=await fileToBase64(f);const result=await ai('ocr',{image:base64,media_type:f.type});text=result.text||'';}else{text=await f.text();}if(text.length>120000)text=text.slice(0,120000);$('lessonBody').value+=($('lessonBody').value?'\n\n':'')+text;toast('Imported '+f.name);}catch(err){toast(err.message,true)}};
 $('summarize').onclick=async()=>{if(!val('lessonBody'))return toast('Add some lesson notes first',true);try{const r=await ai('summarize',{text:val('lessonBody')});$('lessonBody').value=r.text||val('lessonBody');toast('AI summary prepared. Review it before saving.');}catch(e){toast(e.message,true)}};
 const save=async(published)=>{if(!val('lessonTitle')||!val('lessonBody')||!val('lessonClass')||!val('lessonSubject'))return toast('Enter title, class, subject and notes.',true);const r=await db.from('lesson_notes').insert({teacher_id:user.id,class_id:val('lessonClass'),subject_id:val('lessonSubject'),title:val('lessonTitle'),body:val('lessonBody'),published});toast(r.error?.message||'Lesson saved',Boolean(r.error));if(!r.error)go('Lessons');};
 $('saveLesson').onclick=()=>save(false);$('publishLesson').onclick=()=>save(true);
}
const fileToBase64=async f=>{const bytes=new Uint8Array(await f.arrayBuffer());let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.slice(i,i+8192));return btoa(s)};
async function ai(action,body){const r=await db.functions.invoke('school-ai',{body:{action,...body}});if(r.error)throw new Error('AI service is not available: '+r.error.message);if(r.data?.error)throw new Error(r.data.error);return r.data||{};}

async function examinations(){if(!isStaff())return;const [exams,classes,subjects]=await Promise.all([data(db.from('exams').select('*').order('created_at',{ascending:false})),data(db.from('classes').select('id,name')),data(db.from('subjects').select('id,name'))]);const cm=Object.fromEntries(classes.map(c=>[c.id,c.name])),sm=Object.fromEntries(subjects.map(s=>[s.id,s.name]));
 setPage(`<div class="card"><h2>Create examination</h2><p class="muted tiny">Create an assessment, add or generate questions, then publish when reviewed.</p><div class="form-grid">${field('Exam title','examTitle','text','placeholder="e.g. JSS 2 Mathematics First Term"')}${selectField('Class','examClass',options(classes))}${selectField('Subject','examSubject',options(subjects))}${field('Duration (minutes)','examDuration','number','value="60" min="5" max="240"')}${field('Start time (optional)','examStart','datetime-local')}${field('End time (optional)','examEnd','datetime-local')}${area('Instructions','examInstructions','Instructions shown before the examination')}</div>${btn('Create draft exam','createExam')}</div><div class="card"><h2>Exam management</h2>${listTable(exams,['Assessment','Class / subject','Time','Status','Actions'],e=>`<tr><td><b>${esc(e.title)}</b><div class="tiny muted">${fmtDate(e.created_at)}</div></td><td>${esc(cm[e.class_id]||'—')} · ${esc(sm[e.subject_id]||'—')}</td><td>${esc(e.duration_minutes)} min</td><td>${tag(e.published?'Published':'Draft',e.published?'green':'orange')}</td><td><button class="btn secondary small" data-manage="${esc(e.id)}">Manage</button></td></tr>`)}</div><div id="examEditor"></div>`);
 $('createExam').onclick=async()=>{if(!val('examTitle')||!val('examClass')||!val('examSubject'))return toast('Enter exam title, class and subject.',true);let payload={teacher_id:user.id,class_id:val('examClass'),subject_id:val('examSubject'),title:val('examTitle'),duration_minutes:Number(val('examDuration'))||60,instructions:val('examInstructions'),starts_at:val('examStart')?new Date(val('examStart')).toISOString():null,ends_at:val('examEnd')?new Date(val('examEnd')).toISOString():null};const r=await db.from('exams').insert(payload).select('id').single();if(r.error)return toast(r.error.message,true);toast('Exam draft created. Add questions before publishing.');await go('Examinations');};
 document.querySelectorAll('[data-manage]').forEach(b=>b.onclick=()=>editExam(b.dataset.manage));}
async function editExam(examId){const [exam,questions,keys,notes]=await Promise.all([data(db.from('exams').select('*').eq('id',examId).single()),data(db.from('questions').select('*').eq('exam_id',examId).order('position')),data(db.from('question_keys').select('*')),data(db.from('lesson_notes').select('id,title,body').limit(100))]);const keyMap=Object.fromEntries(keys.map(x=>[x.question_id,x]));const editor=$('examEditor');if(!editor)return;
 editor.innerHTML=`<div class="card"><div class="row between"><div><div class="eyebrow">QUESTION BANK</div><h2>${esc(exam.title)}</h2><p class="tiny muted">${questions.length} questions · ${questions.reduce((s,q)=>s+Number(q.marks||0),0)} marks</p></div><div class="row">${btn(exam.published?'Unpublish exam':'Publish exam','toggleExam','secondary')}${btn('View submissions','viewSubmissions','secondary')}</div></div>${questions.length?questions.map((q,i)=>`<div class="question"><div class="row between"><b>${i+1}. ${esc(q.prompt)}</b>${tag(q.question_type,q.question_type==='mcq'?'green':'orange')}</div><p class="tiny muted">${q.marks} marks</p>${q.question_type==='mcq'?'<ol type="A">'+(q.options||[]).map((o,i)=>`<li style="margin:5px 0">${esc(o)} ${keyMap[q.id]?.correct_answer===i?'✓':''}</li>`).join('')+'</ol>':'<p class="muted tiny">Theory answer: teacher-marked</p>'}</div>`).join(''):empty('No questions yet','Add questions manually or generate an AI draft from a lesson note.')}</div><div class="split"><div class="card"><h2>Add a question</h2><div class="form-grid">${selectField('Question type','questionType','<option value="mcq">Objective / MCQ</option><option value="theory">Theory</option>')}${field('Marks','questionMarks','number','min="1" max="100" value="1"')}${area('Question','questionPrompt','Type the complete question')}${area('Options — one per line','questionOptions','Option A\nOption B\nOption C\nOption D')}${selectField('Correct answer','correctIndex','<option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option>')}</div>${btn('Save question','saveQuestion')}</div><div class="card"><h2>Generate from lesson notes</h2><p class="muted tiny">AI-generated questions are always drafts until a teacher reviews and publishes the exam.</p>${selectField('Choose lesson source','aiLesson',options(notes,'title'))}${selectField('Question type','aiType','<option value="mcq">Multiple choice</option><option value="theory">Theory</option>')}${field('Number of questions','aiCount','number','value="5" min="1" max="20"')}${btn('✨ Generate question draft','aiGenerate','secondary')}<div id="aiQuestions"></div></div></div>`;
 $('questionType').onchange=()=>{$('questionOptions').closest('.field').hidden=val('questionType')==='theory';$('correctIndex').closest('.field').hidden=val('questionType')==='theory';};
 $('toggleExam').onclick=async()=>{if(!exam.published&&!questions.length)return toast('Add at least one question before publishing.',true);let r=await db.from('exams').update({published:!exam.published}).eq('id',examId);toast(r.error?.message||'Exam visibility updated',Boolean(r.error));if(!r.error)go('Examinations');};
 $('viewSubmissions').onclick=()=>go('Marking');
 $('saveQuestion').onclick=async()=>{try{await insertQuestion(examId,{prompt:val('questionPrompt'),question_type:val('questionType'),marks:Number(val('questionMarks')),options:val('questionOptions').split('\n').map(x=>x.trim()).filter(Boolean),correct: Number(val('correctIndex'))},questions.length+1);toast('Question added');await editExam(examId);}catch(e){toast(e.message,true)}};
 $('aiGenerate').onclick=async()=>{let lesson=notes.find(n=>n.id===val('aiLesson'));if(!lesson)return toast('Select a lesson note.',true);$('aiGenerate').disabled=true;try{const r=await ai('generate_questions',{text:lesson.body,type:val('aiType'),count:Math.min(20,Math.max(1,Number(val('aiCount'))||5))});const draft=r.questions||[];if(!Array.isArray(draft)||!draft.length)throw Error('AI returned no questions.');$('aiQuestions').innerHTML=`<div class="notice">${draft.length} AI questions generated. Review carefully before importing.</div>${draft.map((q,i)=>`<div class="question"><b>${esc(q.prompt)}</b><p class="tiny muted">${esc(q.type||q.question_type)} · ${esc((q.options||[]).join(' · '))}</p></div>`).join('')}${btn('Import reviewed drafts','importAi')}`;$('importAi').onclick=async()=>{if(!confirm('Have you reviewed the questions and answer keys? Import to this exam draft?'))return;try{let i=questions.length+1;for(const q of draft){await insertQuestion(examId,{prompt:q.prompt,question_type:q.type==='theory'?'theory':'mcq',marks:Number(q.marks||1),options:q.options||[],correct:Number(q.correct_index||0)},i++);}toast('Imported '+draft.length+' questions. Review the exam again before publishing.');await editExam(examId);}catch(e){toast(e.message,true)}};}catch(e){toast(e.message,true)}finally{if($('aiGenerate'))$('aiGenerate').disabled=false;}};
}
async function insertQuestion(examId,q,position){if(!q.prompt||!q.marks||q.marks<0)return Promise.reject(Error('Enter the question and a valid mark value.'));if(q.question_type==='mcq'&&(!Array.isArray(q.options)||q.options.length<2||q.correct>=q.options.length))throw Error('MCQ questions need valid options and a correct answer.');let r=await db.from('questions').insert({exam_id:examId,position,question_type:q.question_type,prompt:q.prompt,options:q.question_type==='mcq'?q.options:null,marks:q.marks}).select('id').single();if(r.error)throw r.error;if(q.question_type==='mcq'){let k=await db.from('question_keys').insert({question_id:r.data.id,correct_answer:q.correct});if(k.error)throw new Error('Question created, but answer key failed: '+k.error.message);}return r.data;}

async function takeExam(){if(profile.role!=='student')return;const [exams,attempts,classes]=await Promise.all([data(db.from('exams').select('*').eq('published',true)),data(db.from('exam_attempts').select('exam_id,score,submitted_at')),data(db.from('classes').select('id,name'))]);const cm=Object.fromEntries(classes.map(x=>[x.id,x.name]));const attempted=new Set(attempts.map(a=>a.exam_id));setPage(`<div class="card"><h2>Available examinations</h2><p class="muted tiny">Complete each exam once. Answers are submitted securely for automatic objective marking and teacher review of theory questions.</p>${listTable(exams,['Exam','Class','Duration','Status','Action'],e=>`<tr><td><b>${esc(e.title)}</b><div class="tiny muted">${esc(e.instructions||'')}</div></td><td>${esc(cm[e.class_id]||'—')}</td><td>${esc(e.duration_minutes)} min</td><td>${attempted.has(e.id)?tag('Submitted','green'):tag('Ready','orange')}</td><td>${attempted.has(e.id)?'—':`<button class="btn small" data-start="${esc(e.id)}">Start exam →</button>`}</td></tr>`)}</div><div id="testArea"></div>`);document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>examScreen(b.dataset.start,exams.find(e=>e.id===b.dataset.start)));}
async function examScreen(id,exam){const qs=await data(db.from('questions').select('id,prompt,question_type,options,marks').eq('exam_id',id).order('position'));if(!qs.length)return toast('No questions have been published for this exam.',true);$('testArea').innerHTML=`<div class="card"><div class="row between"><h2>${esc(exam.title)}</h2>${tag('Time remaining: '+exam.duration_minutes+' min','orange')}</div><p class="muted tiny">${esc(exam.instructions||'Answer all questions carefully, then submit once.')}</p><form id="examForm">${qs.map((q,i)=>`<div class="question"><b>${i+1}. ${esc(q.prompt)}</b> ${tag(q.marks+' marks')}<div style="margin-top:12px">${q.question_type==='mcq'?(q.options||[]).map((o,j)=>`<label class="option"><input type="radio" name="q_${i}" value="${j}"> ${String.fromCharCode(65+j)}. ${esc(o)}</label>`).join(''):`<div class="field"><textarea name="q_${i}" placeholder="Write your answer"></textarea></div>`}</div></div>`).join('')}<div class="row between"><strong id="examTime">${esc(exam.duration_minutes)}:00</strong><button class="btn" type="submit" id="submitExam">Submit examination</button></div></form></div>`;let seconds=Number(exam.duration_minutes)*60;localTimer=setInterval(()=>{seconds=Math.max(0,seconds-1);if($('examTime'))$('examTime').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(!seconds){clearInterval(localTimer);localTimer=null;toast('Exam timer ended. Submit your answers now.',true);}},1000);
 $('examForm').onsubmit=async e=>{e.preventDefault();if(!confirm('Submit your exam? You cannot submit it again.'))return;const button=$('submitExam');button.disabled=true;const form=new FormData(e.target);const answers=qs.map((q,i)=>({question_id:q.id,response:q.question_type==='mcq'?(form.get('q_'+i)!==null?Number(form.get('q_'+i)):null):(form.get('q_'+i)||'').toString()}));let r=await db.rpc('submit_exam',{p_exam:id,p_answers:answers});if(r.error){button.disabled=false;return toast(r.error.message,true);}const result=r.data||{};clearInterval(localTimer);localTimer=null;$('testArea').innerHTML=`<div class="card"><h2>Examination submitted ✓</h2><div class="notice ok">Your answers have been saved securely.</div><p>Objective score: <b>${esc(result.objective_score)} / ${esc(result.total_marks)}</b></p><p>${result.theory_pending?result.theory_pending+' theory answer(s) await teacher marking.':'Your objective answers were marked automatically.'}</p>${btn('View my results','viewMyResults')}</div>`;$('viewMyResults').onclick=()=>go('My Results');};}
async function myResults(){const [attempts,exams]=await Promise.all([data(db.from('exam_attempts').select('id,exam_id,score,submitted_at').order('submitted_at',{ascending:false})),data(db.from('exams').select('id,title'))]);const em=Object.fromEntries(exams.map(e=>[e.id,e.title]));setPage(`<div class="card"><h2>My exam results</h2><p class="muted tiny">Objective marks are automatic. Theory marks remain provisional until reviewed by your teacher.</p>${listTable(attempts,['Exam','Submitted','Recorded score','Status'],a=>`<tr><td><b>${esc(em[a.exam_id]||'Exam')}</b></td><td>${fmtDate(a.submitted_at)}</td><td>${esc(a.score??'Awaiting marking')}</td><td>${tag('Recorded','green')}</td></tr>`)}</div>`);}
async function grading(){if(!isStaff())return;const [exams,attempts,profiles]=await Promise.all([data(db.from('exams').select('id,title')),data(db.from('exam_attempts').select('*').order('submitted_at',{ascending:false})),data(db.from('profiles').select('id,full_name'))]);const em=Object.fromEntries(exams.map(e=>[e.id,e.title])),pm=Object.fromEntries(profiles.map(p=>[p.id,p.full_name]));setPage(`<div class="card"><h2>Marking & submissions</h2><p class="muted tiny">Objective answers are graded automatically when submitted. Teachers enter theory marks, and totals recalculate securely.</p>${listTable(attempts,['Learner','Exam','Submitted','Current score','Action'],a=>`<tr><td><b>${esc(pm[a.student_id]||a.student_id)}</b></td><td>${esc(em[a.exam_id]||'Exam')}</td><td>${fmtDate(a.submitted_at)}</td><td>${esc(a.score??'—')}</td><td><button class="btn secondary small" data-attempt="${esc(a.id)}">Review</button></td></tr>`)}</div><div id="markArea"></div>`);document.querySelectorAll('[data-attempt]').forEach(b=>b.onclick=()=>reviewAttempt(b.dataset.attempt));}
async function reviewAttempt(attemptId){const [answers,qs]=await Promise.all([data(db.from('student_answers').select('id,question_id,answer,awarded_marks').eq('attempt_id',attemptId)),data(db.from('questions').select('id,prompt,marks,question_type'))]);const qm=Object.fromEntries(qs.map(q=>[q.id,q]));$('markArea').innerHTML=`<div class="card"><h2>Answer review</h2>${answers.length?answers.map(a=>{const q=qm[a.question_id];if(!q)return '';return `<div class="question"><div class="row between"><b>${esc(q.prompt)}</b>${tag(q.question_type)}</div><p style="white-space:pre-wrap">${esc(a.answer?.response)}</p><p class="tiny muted">${esc(a.awarded_marks??'Pending')} / ${esc(q.marks)} marks</p>${q.question_type==='theory'?`<div class="row"><input style="max-width:120px;padding:9px;border:1px solid #e1d4de;border-radius:9px" type="number" min="0" max="${esc(q.marks)}" step="0.5" id="mark_${esc(a.id)}" value="${esc(a.awarded_marks??0)}"><button class="btn small" data-mark="${esc(a.id)}">Save mark</button></div>`:''}</div>`;}).join(''):empty('No answers') }</div>`;document.querySelectorAll('[data-mark]').forEach(b=>b.onclick=async()=>{const a=answers.find(x=>x.id===b.dataset.mark),q=qm[a.question_id],marks=Number(val('mark_'+a.id));if(!Number.isFinite(marks)||marks<0||marks>Number(q.marks))return toast('Marks must be between 0 and '+q.marks,true);let r=await db.rpc('mark_theory_answer',{p_answer:a.id,p_marks:marks});toast(r.error?.message||'Mark recorded. Total recalculated.',Boolean(r.error));if(!r.error)await reviewAttempt(attemptId);});}

async function attendance(){const [classes,enrollments,profiles,previous]=await Promise.all([data(db.from('classes').select('id,name')),data(db.from('enrollments').select('student_id,class_id')),data(db.from('profiles').select('id,full_name')),data(db.from('attendance').select('student_id,class_id,day,status').order('day',{ascending:false}).limit(300))]);const cm=Object.fromEntries(classes.map(x=>[x.id,x.name])),pm=Object.fromEntries(profiles.map(x=>[x.id,x.full_name]));const staff=isStaff();
 setPage(`${staff?`<div class="card"><h2>Record attendance</h2><div class="form-grid">${selectField('Class','attendanceClass',options(classes))}${field('Date','attendanceDate','date',`value="${new Date().toLocaleDateString('en-CA')}"`)}</div>${btn('Load class register','loadRegister','secondary')}<div id="register"></div></div>`:''}<div class="card"><h2>${staff?'Recent attendance':'Attendance history'}</h2>${listTable(previous,['Student','Class','Date','Status'],r=>`<tr><td>${esc(pm[r.student_id]||'Your child / student')}</td><td>${esc(cm[r.class_id]||'Class')}</td><td>${fmtDate(r.day+'T00:00:00')}</td><td>${tag(r.status,r.status==='present'?'green':r.status==='absent'?'orange':'gray')}</td></tr>`)}</div>`);
 if(!staff)return;
 $('loadRegister').onclick=async()=>{const classId=val('attendanceClass'),day=val('attendanceDate');if(!classId||!day)return toast('Select class and date.',true);const members=enrollments.filter(x=>x.class_id===classId), existing=await data(db.from('attendance').select('*').eq('class_id',classId).eq('day',day));const am=Object.fromEntries(existing.map(x=>[x.student_id,x.status]));$('register').innerHTML=`<h3 style="margin:20px 0">Register: ${esc(cm[classId])} · ${esc(day)}</h3>${members.length?members.map(x=>`<div class="student-row"><b>${esc(pm[x.student_id]||x.student_id)}</b><select class="attendanceStatus" data-student="${esc(x.student_id)}"><option value="present" ${am[x.student_id]==='present'?'selected':''}>Present</option><option value="absent" ${am[x.student_id]==='absent'?'selected':''}>Absent</option><option value="late" ${am[x.student_id]==='late'?'selected':''}>Late</option><option value="excused" ${am[x.student_id]==='excused'?'selected':''}>Excused</option></select></div>`).join(''):empty('No students enrolled','Enroll students in this class first.')} ${members.length?btn('Save attendance register','saveRegister'):''}`;
 if($('saveRegister'))$('saveRegister').onclick=async()=>{const rows=[...document.querySelectorAll('.attendanceStatus')].map(s=>({student_id:s.dataset.student,class_id:classId,day,status:s.value}));let r=await db.from('attendance').upsert(rows,{onConflict:'student_id,class_id,day'});toast(r.error?.message||'Attendance register saved',Boolean(r.error));if(!r.error)go('Attendance');};};}
async function assessments(){if(!isStaff())return;const [classes,subjects,sessions,enrollments,students]=await Promise.all([data(db.from('classes').select('id,name')),data(db.from('subjects').select('id,name')),data(db.from('academic_sessions').select('id,name')),data(db.from('enrollments').select('student_id,class_id')),data(db.from('profiles').select('id,full_name').eq('role','student'))]);const nm=Object.fromEntries(students.map(s=>[s.id,s.full_name]));
 setPage(`<div class="card"><h2>Continuous assessment & exam scores</h2><p class="muted tiny">Enter numeric CA and examination scores. The total shown on report cards is CA + Exam; school-specific grading rules must be confirmed before publishing results.</p><div class="form-grid">${selectField('Class','scoreClass',options(classes))}${selectField('Subject','scoreSubject',options(subjects))}${selectField('Academic session','scoreSession',options(sessions))}${selectField('Term','scoreTerm','<option value="1">First term</option><option value="2">Second term</option><option value="3">Third term</option>')}</div>${btn('Load score sheet','loadScores','secondary')}<div id="scoreSheet"></div></div>`);
 $('loadScores').onclick=async()=>{const classId=val('scoreClass'),subjectId=val('scoreSubject'),sessionId=val('scoreSession'),term=Number(val('scoreTerm'));if(!classId||!subjectId||!sessionId)return toast('Choose class, subject and session',true);const sids=enrollments.filter(e=>e.class_id===classId).map(e=>e.student_id),existing=await data(db.from('assessments').select('*').eq('subject_id',subjectId).eq('session_id',sessionId).eq('term',term));const em=Object.fromEntries(existing.map(e=>[e.student_id,e]));$('scoreSheet').innerHTML=`<div style="height:20px"></div><h3>Score entry</h3>${sids.length?`<div class="scroll"><table><thead><tr><th>Student</th><th>CA score</th><th>Exam score</th><th>Teacher comment</th></tr></thead><tbody>${sids.map(s=>`<tr data-score-student="${esc(s)}"><td>${esc(nm[s]||s)}</td><td><input type="number" class="caScore" min="0" step="0.5" value="${esc(em[s]?.ca_score??0)}" style="width:96px;border:1px solid #eee;padding:9px"></td><td><input type="number" class="examScore" min="0" step="0.5" value="${esc(em[s]?.exam_score??0)}" style="width:96px;border:1px solid #eee;padding:9px"></td><td><input class="teacherComment" value="${esc(em[s]?.teacher_comment||'')}" style="width:220px;border:1px solid #eee;padding:9px"></td></tr>`).join('')}</tbody></table></div>`:empty('No enrolled students')} ${sids.length?btn('Save score sheet','saveScores'):''}`;
 if($('saveScores'))$('saveScores').onclick=async()=>{const rows=[...document.querySelectorAll('[data-score-student]')].map(tr=>({student_id:tr.dataset.scoreStudent,subject_id:subjectId,session_id:sessionId,term,ca_score:Number(tr.querySelector('.caScore').value),exam_score:Number(tr.querySelector('.examScore').value),teacher_comment:tr.querySelector('.teacherComment').value}));let r=await db.from('assessments').upsert(rows,{onConflict:'student_id,subject_id,session_id,term'});toast(r.error?.message||'Assessment scores saved',Boolean(r.error));};};}
async function reportCards(){const [students,sessions,subjects,cards,assessments]=await Promise.all([data(db.from('profiles').select('id,full_name,admission_number').eq('role','student')),data(db.from('academic_sessions').select('id,name')),data(db.from('subjects').select('id,name')),data(db.from('report_cards').select('*')),data(db.from('assessments').select('*'))]);const sm=Object.fromEntries(subjects.map(s=>[s.id,s.name]));const studentsById=Object.fromEntries(students.map(s=>[s.id,s]));const admin=profile.role==='admin';
 setPage(`<div class="card no-print"><h2>Student report card</h2><p class="muted tiny">Only approved report cards are shared with students and parents. Schools should verify their marking scheme before approval.</p><div class="form-grid">${selectField('Student','reportStudent',options(students,'full_name'))}${selectField('Academic session','reportSession',options(sessions))}${selectField('Term','reportTerm','<option value="1">First term</option><option value="2">Second term</option><option value="3">Third term</option>')}</div>${btn('View report card','viewReport','secondary')} ${admin?btn('Approve selected report','approveReport'):''}</div><div id="reportViewer"></div>`);
 const selected=()=>({student_id:val('reportStudent'),session_id:val('reportSession'),term:Number(val('reportTerm'))});const view=()=>{const p=selected();if(!p.student_id||!p.session_id)return toast('Select student and session',true);const record=cards.find(c=>c.student_id===p.student_id&&c.session_id===p.session_id&&c.term===p.term);const rows=assessments.filter(a=>a.student_id===p.student_id&&a.session_id===p.session_id&&a.term===p.term);const marks=rows.map(a=>({name:sm[a.subject_id]||a.subject_id,ca:Number(a.ca_score||0),exam:Number(a.exam_score||0),total:Number(a.ca_score||0)+Number(a.exam_score||0),comment:a.teacher_comment||''}));const student=studentsById[p.student_id];$('reportViewer').innerHTML=`<div class="report"><div class="report-head"><div class="eyebrow">${esc(schoolMotto)}</div><h2>${esc(schoolName)}</h2><p class="tiny muted">Academic performance report</p>${tag(record?.approved_at?'Approved':'Draft — not approved',record?.approved_at?'green':'orange')}</div><div class="form-grid"><p><b>Student:</b> ${esc(student?.full_name||'Student')}</p><p><b>Admission number:</b> ${esc(student?.admission_number||'—')}</p><p><b>Session:</b> ${esc(sessions.find(s=>s.id===p.session_id)?.name)}</p><p><b>Term:</b> ${p.term}</p></div>${listTable(marks,['Subject','CA','Exam','Total','Comment'],a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.ca)}</td><td>${esc(a.exam)}</td><td><b>${esc(a.total)}</b></td><td>${esc(a.comment)}</td></tr>`)}<div class="row between" style="margin-top:24px"><b>Total across subjects: ${marks.reduce((s,a)=>s+a.total,0)}</b><span class="tiny muted">${record?.approved_at?'Approved '+fmtDate(record.approved_at):'Awaiting principal approval'}</span></div><p><b>Remarks:</b> ${esc(record?.remarks||'—')}</p><button class="btn secondary no-print" id="printReport">Print or save as PDF</button></div>`;$('printReport').onclick=()=>window.print();};$('viewReport').onclick=view;
 if(admin)$('approveReport').onclick=async()=>{const p=selected();if(!p.student_id||!p.session_id)return toast('Select student and session',true);if(!confirm('Approve and publish this student report card?'))return;let r=await db.from('report_cards').upsert({...p,approved_by:user.id,approved_at:new Date().toISOString()},{onConflict:'student_id,session_id,term'});toast(r.error?.message||'Report card approved',Boolean(r.error));if(!r.error)go('Report Cards');};}

async function announcements(){const news=await data(db.from('announcements').select('*').order('created_at',{ascending:false}).limit(100));setPage(`${isStaff()?`<div class="card"><h2>Publish school announcement</h2>${field('Announcement title','announcementTitle','text','placeholder="Important school update"')}${area('Message','announcementBody','Enter your announcement')}${btn('Publish announcement','sendAnnouncement')}</div>`:''}<div class="card"><h2>School news & updates</h2>${news.length?news.map(n=>`<div class="question"><div class="row between"><h3>${esc(n.title)}</h3><span class="muted tiny">${fmtDate(n.created_at)}</span></div><p style="white-space:pre-wrap">${esc(n.body)}</p></div>`).join(''):empty('No announcements yet')}</div>`);if($('sendAnnouncement'))$('sendAnnouncement').onclick=async()=>{if(!val('announcementTitle')||!val('announcementBody'))return toast('Add an announcement title and message',true);let r=await db.from('announcements').insert({school_id:profile.school_id,author_id:user.id,title:val('announcementTitle'),body:val('announcementBody')});toast(r.error?.message||'Announcement published',Boolean(r.error));if(!r.error)go('Announcements');};}
async function children(){if(profile.role!=='parent')return;const [links,profiles]=await Promise.all([data(db.from('parent_students').select('student_id')),data(db.from('profiles').select('id,full_name,admission_number'))]);const pm=Object.fromEntries(profiles.map(p=>[p.id,p]));setPage(`<div class="card"><h2>My children</h2><p class="muted tiny">Your parent account can only view students assigned to you by school administration.</p><div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))">${links.map(l=>`<div class="stat"><div class="icon">♧</div><b style="font-size:19px">${esc(pm[l.student_id]?.full_name||'Student')}</b><div class="meta">${esc(pm[l.student_id]?.admission_number||'Admission number pending')}</div></div>`).join('')||empty('No children linked')}</div></div>`);}

